// ── Étape 1 : Validation + Détection Automatique buyer/seller ────────
const body = $input.first().json.body || $input.first().json;

// Extraction champs Waalaxy
const firstName   = (body.firstName   || body.first_name  || '').trim();
const lastName    = (body.lastName    || body.last_name   || '').trim();
const linkedinUrl = (body.linkedinUrl || body.linkedin_url || body.linkedin || '').trim();
const company     = (body.company     || body.organization || '').trim();
const zone        = (body.zone        || body.location     || body.city    || '').trim();
const campaignName = (body.campaignName || body.campaign_name || body.listName || '').toLowerCase();
const email        = body.email || '';

// Validation minimale
if (!firstName && !lastName && !linkedinUrl) {
  throw new Error('Payload Waalaxy invalide : nom ou LinkedIn URL obligatoire.');
}

// ── Détection automatique lead_type depuis le nom de campagne ──────
// Campagne Acheteurs  : contient 'achet', 'buyer', 'acquér', 'invest', 'premier', 'achat'
// Campagne Vendeurs   : contient 'vend', 'seller', 'mandat', 'proprié', 'cession'
let lead_type = 'buyer'; // défaut : acheteur

const sellerKeywords = ['vend', 'seller', 'mandat', 'proprié', 'cession', 'heritage', 'succession', 'dpe'];
const buyerKeywords  = ['achet', 'buyer', 'acquér', 'invest', 'premier', 'achat', 'recherch'];

const isSellerCampaign = sellerKeywords.some(kw => campaignName.includes(kw));
const isBuyerCampaign  = buyerKeywords.some(kw  => campaignName.includes(kw));

if (isSellerCampaign && !isBuyerCampaign) {
  lead_type = 'seller';
} else {
  lead_type = 'buyer';
}

// Normalisation URL LinkedIn
let cleanLinkedin = linkedinUrl;
if (cleanLinkedin && !cleanLinkedin.startsWith('http')) {
  cleanLinkedin = 'https://linkedin.com/in/' + cleanLinkedin;
}

return [{
  json: {
    firstName,
    lastName,
    fullName: (firstName + ' ' + lastName).trim(),
    linkedinUrl: cleanLinkedin,
    company,
    zone,
    email,
    lead_type,
    campaignName,
    source: 'waalaxy',
    raw_payload: JSON.stringify(body)
  }
}];

// ── Construction prompt Gemma 4 – ACHETEUR (BUYER) ──────────────────
const d = $input.first().json;

const prompt = `Tu es un expert en scoring de leads immobiliers. Analyse ce profil ACHETEUR et retourne UNIQUEMENT un objet JSON valide, sans markdown.

PROFIL ACHETEUR:
- Nom: ${d.fullName}
- Entreprise: ${d.company}
- Zone recherchée: ${d.zone}
- Source: ${d.source}
- LinkedIn: ${d.linkedinUrl}

Critères de scoring ACHETEUR (capacité financière, urgence projet, engagement):
- Score élevé (70-100) = prêt à acheter, projet immédiat, budget confirmé
- Score moyen (40-70) = projet à 3-6 mois, intérêt confirmé
- Score faible (0-40) = intention vague, projet long terme

Réponds UNIQUEMENT avec ce JSON (rien d'autre):
{"score": <entier 0-100>, "category": "hot" ou "warm" ou "cold", "justification": "<une phrase courte>"}`;

return [{ json: { ...d, gemma_prompt: prompt } }];

// ── Construction prompt Gemma 4 – VENDEUR (SELLER) ──────────────────
const d = $input.first().json;

const prompt = `Tu es un expert en scoring de leads immobiliers. Analyse ce profil VENDEUR et retourne UNIQUEMENT un objet JSON valide, sans markdown.

PROFIL VENDEUR:
- Nom: ${d.fullName}
- Entreprise: ${d.company}
- Zone du bien: ${d.zone}
- Source: ${d.source}
- LinkedIn: ${d.linkedinUrl}
- Campagne: ${d.campaignName}

Critères de scoring VENDEUR (urgence de vente, signaux comportementaux):
- Score élevé (70-100) = urgence forte (succession, DPE récent, >7 ans de propriété, listé sans agence)
- Score moyen (40-70) = intention de vente confirmée, délai 3-6 mois
- Score faible (0-40) = signal faible, réflexion préliminaire

Réponds UNIQUEMENT avec ce JSON (rien d'autre):
{"score": <entier 0-100>, "category": "hot" ou "warm" ou "cold", "justification": "<une phrase courte>"}`;

return [{ json: { ...d, gemma_prompt: prompt } }];

// ── Parser réponse Gemma 4 – format OpenAI (choices[0].message.content) ──
const gemmaResponse = $input.first().json;
const inputData     = $('Construire Prompt Buyer').first().json;

let score = 50, category = 'warm', justification = 'Scoring automatique Gemma 4', ia_fallback = false;

try {
  const rawText = (
    gemmaResponse?.choices?.[0]?.message?.content ||
    gemmaResponse?.message?.content ||
    gemmaResponse?.response || '{}'
  ).trim()
   .replace(/```json\s*/gi, '')
   .replace(/```\s*/g, '')
   .trim();

  const parsed = JSON.parse(rawText);
  score = Math.max(0, Math.min(100, parseInt(parsed.score) || 50));
  justification = parsed.justification || 'Scoring Gemma 4 buyer';

  const rawCat = (parsed.category || '').toLowerCase();
  if (['hot', 'chaud'].includes(rawCat) || score > 70)       category = 'hot';
  else if (['cold', 'froid'].includes(rawCat) || score < 40) category = 'cold';
  else                                                         category = 'warm';

} catch(e) {
  ia_fallback = true;
  score = 50; category = 'warm';
  justification = 'Fallback – erreur parsing Gemma 4 buyer: ' + e.message;
  console.error('[Galacs BUYER] Parsing error:', e.message);
}

return [{ json: { ...inputData, score, category, justification, ia_fallback, model_version: 'gemma4:latest' } }];

