// ── Fusion Score Buyer + Email Dropcontact ────────────────────────────
const scoredData = $('Parser Score Buyer').first().json;
const dropResp   = $input.first().json;

let email = scoredData.email || '';
let dropcontact_found = false;

try {
  const data = dropResp.data || dropResp.contacts || [];
  if (data.length > 0) {
    const contact = data[0];
    const emails  = contact.email || [];
    if (Array.isArray(emails) && emails.length > 0) {
      const best = emails.sort((a, b) => (b.confidence || 0) - (a.confidence || 0))[0];
      if (best?.email) { email = best.email; dropcontact_found = true; }
    } else if (typeof emails === 'string' && emails.includes('@')) {
      email = emails; dropcontact_found = true;
    }
  }
} catch(e) { dropcontact_found = false; }

return [{ json: { ...scoredData, email, dropcontact_found } }];

