// ── Vérification réponse Odoo Buyer ────────────────────────────────────
const odooResp = $input.first().json;
const lead     = $('Fusionner Buyer (Score + Email)').first().json;

// Unwrap JSON-RPC wrapper { jsonrpc, id, result: {...} }
const result        = odooResp.result || odooResp;

const success       = result.success === true;
const dedup_blocked = result.dedup_blocked === true;
const lead_id       = result.lead_id || null;

console.log(`[Galacs BUYER] "${lead.fullName}" | success=${success} | dedup=${dedup_blocked} | lead_id=${lead_id} | score=${lead.score}% | category=${lead.category}`);

if (!success && !dedup_blocked) {
  throw new Error(`Odoo buyer import failed: ${result.error || 'Unknown error'}`);
}

return [{ json: {
  success,
  dedup_blocked,
  lead_id,
  lead_type: 'buyer',
  lead_name: lead.fullName,
  email:     lead.email,
  score:     lead.score,
  category:  lead.category,
  timestamp: new Date().toISOString(),
  message:   result.message || (dedup_blocked ? 'Doublon buyer bloqué (30j)' : 'Lead buyer créé avec succès')
} }];

